const item = $json;
const annee = new Date(item.date).getFullYear();
const queries = [
  `"${item.theme_label}" facebook ads library publicite`,
  `${item.theme_label} tiktok shop viral ${annee}`,
  `${item.theme_label} influenceur ugc publicite tendance`,
  `${item.theme_label} pinterest tendance ${annee}`,
  `${item.theme_label} black friday ${annee} marketing idee campagne`
];
return [{ json: { ...item, searchBody: queries.map(q => ({ q, gl: 'fr', hl: 'fr', num: 5 })) } }];

const item = $('Construire requetes recherche').item.json;
const batchResults = $json;

let lines = [];
let seen = new Set();
for (const result of (Array.isArray(batchResults) ? batchResults : [batchResults])) {
  for (const o of (result.organic || [])) {
    if (!o.link || seen.has(o.link)) continue;
    seen.add(o.link);
    lines.push(`- [${o.title}](${o.link}) — ${o.snippet || ''}`);
  }
}
const resultatsRecherche = lines.length
  ? lines.join('\n')
  : "(aucun resultat exploitable trouve par la recherche n8n pour ces requetes — le dire honnetement dans le rapport plutot que d'inventer)";

const prompt = `Tu es l'agent MARKETING specialise de la categorie "${item.categorie_label}" pour le site de dropshipping drop-shipper.fr.
Rapport du jour : ${item.date}, sous-theme "${item.theme_label}" (id: ${item.theme_id}).

Tu ne fais PAS de recherche web toi-meme : n8n a deja execute les requetes et te fournit ci-dessous les resultats REELS (titre, URL, extrait) obtenus sur le web au sujet des publicites, tendances et reseaux sociaux lies a ce theme.
REGLE ABSOLUE : appuie-toi uniquement sur ces resultats. Si Facebook Ads Library ou une autre source n'apparait pas dedans (acces souvent bloque aux robots), dis-le explicitement plutot que d'inventer une donnee, et utilise les sources tierces presentes a la place.

Analyse en profondeur a partir de ces resultats : publicites qui convertissent sur ce theme, depuis combien de temps diffusees, vendeurs, createurs en charge, couts de campagne si l'info apparait. Couvre TikTok Ads et TikTok Shop, Meta/Instagram, Pinterest. Ajoute des conseils produits tendance du moment sur les reseaux, des conseils marketing, la preparation marketing pour les fetes a venir avec dates verifiees, et des idees de campagnes. Termine par 5 prompts de creation d'image publicitaire statique et 5 prompts de video courte publicitaire, prets a etre utilises avec un outil de generation IA (destines a Lea, notre agent graphiste).

Respecte EXACTEMENT ce contrat de sortie (Markdown, rien avant ni apres) :

---
type: marketing
date: ${item.date}
categorie: ${item.categorie_id}
theme: ${item.theme_id}
titre: <titre court en francais>
agent: marketing-${item.categorie_id}
sources: <nombre de sources distinctes citees>
---

## Social places
## Publicités en cours
## Tendances du jour
## Tendances publicitaires
## Prompts d'images publicitaires
(5 blocs de code Markdown autonomes, premiere ligne = commentaire de format, ex "# Facebook 1:1")
## Prompts de vidéos publicitaires
(5 blocs de code Markdown autonomes, premiere ligne = commentaire de format, ex "# TikTok 9:16 — 15 s")

Les six sections doivent apparaitre EXACTEMENT dans cet ordre. Reponds en francais.

Resultats de recherche web (fournis par n8n) :
${resultatsRecherche}`;

return [{ json: { ...item, marketingPrompt: prompt } }];

const response = $json;
const markdown = (response.response || '').trim();
const item = $('Agreger recherche + construire prompt').item.json;
const binary = await this.helpers.prepareBinaryData(Buffer.from(markdown, 'utf8'), `${item.theme_id}.marketing.md`, 'text/markdown');
return [{ json: { ...item, marketingMarkdown: markdown, marketingPath: `${item.basePath}/rapports/${item.date}/${item.categorie_id}/${item.theme_id}.marketing.md` }, binary: { data: binary } }];
